func UnitStateLoadMeasure(wire []byte) int64 {
	n, _, _ := tableRegionMeasure(wire, UnitStateTableType(), UnitStateTableType().NodeType, 2)
	return n
}
func UnitStateLoadMeasureReason(wire []byte) (int64, error) {
	size, _, _, reason := tableRegionMeasureReason(wire, UnitStateTableType(), UnitStateTableType().NodeType, 2)
	return size, tableRefuseError(reason)
}
func UnitStateLoad(region, wire []byte, report *TableReport) *UnitState {
	return (*UnitState)(tableRegionLoad(region, wire, UnitStateTableType(), UnitStateTableType().NodeType, 2, report))
}
func UnitStateMeasure(value *UnitState, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), UnitStateTableType(), nil, true, arena, allocator)
}
func UnitStateMeasureReason(value *UnitState, context ...TableWriteContext) (int64, error) {
	arena, allocator := tableWriteOptions(context)
	size, reason := tableRegionSaveReason(unsafe.Pointer(value), UnitStateTableType(), nil, true, arena, allocator)
	return size, tableRefuseError(reason)
}
func UnitStateSave(value *UnitState, buffer []byte, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), UnitStateTableType(), buffer, false, arena, allocator)
}
func UnitStateLoadBuilder(b *UnitStateBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, UnitStateTableType(), UnitStateTableType().NodeType, 2, report)
}

// UnitStateReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func UnitStateReadStrict(wire []byte) (*UnitState, error) {
	var b UnitStateBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := UnitStateLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type UnitStateBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *UnitStateBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(UnitState{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	UnitStateReset((*UnitState)(p))
	return true
}
func (b *UnitStateBuilder) GetRoot() *UnitState {
	if b.Arena.Locked {
		return nil
	}
	return (*UnitState)(b.Arena.At(b.root))
}
func (b *UnitStateBuilder) AsConst() *UnitState {
	if len(b.region) == 0 {
		return nil
	}
	return (*UnitState)(unsafe.Pointer(&b.region[0]))
}
func (b *UnitStateBuilder) Region() []byte { return b.region }
func (b *UnitStateBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), UnitStateTableType(), &b.Arena)
}
func (b *UnitStateBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), UnitStateTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *UnitStateBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), UnitStateTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *UnitStateBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// UnitsCheckReset restores UnitsCheck's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func UnitsCheckReset(value *UnitsCheck) {
	value.Dir = 0
	value.Ok = false
	value.Units = TableList[UnitStateRow]{}
}

func UnitsCheckMeasureBody(value *UnitsCheck, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !UnitsCheckSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func UnitsCheckSaveBody(w *TableWriter, value *UnitsCheck) bool {
	if !UnitsCheckSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func UnitsCheckSaveBodyFields(w *TableWriter, value *UnitsCheck) bool {
	{
		if value.Dir != 0 {
			if ref := w.Ids.refAtHit(273, 0xcaa83e18f46e5f54); !w.headerPair(ref, 17) {
				w.headerRest(ref, 17)
			}
			if value.Dir == 0 {
				if !w.putLebPair(0) {
					w.putLebWide(0)
				}
			} else {
				index, ok := w.Ids.Numbering.Index(&value.Dir)
				if !ok {
					return false
				}
				if !w.putLebPair(index) {
					w.putLebWide(index)
				}
			}
		}
	}
	{
		if value.Ok != false {
			if ref := w.Ids.refAtHit(17, 0x08b05d07b5566bef); !w.headerPair(ref, 1) {
				w.headerRest(ref, 1)
			}
			if value.Ok {
				w.Put8(1)
			} else {
				w.Put8(0)
			}
		}
	}
	{
		if value.Units.Count < 0 {
			return false
		}
		if value.Units.Count > 0 {
			if ref := w.Ids.refAtHit(109, 0x4b78454e9ad2913c); !w.headerPair(ref, 14) {
				w.headerRest(ref, 14)
			}
			if value.Units.Count < 0 {
				return false
			}
			{
				mark := w.Ids.Count
				payload8 := TableWriter{Measuring: true, Ids: w.Ids}
				cursor := tableContainerCursorBegin((*tableContainer)(unsafe.Pointer(&value.Units)), int64(unsafe.Sizeof(*new(UnitStateRow))), w.Ids.Numbering.arena)
				for i := int32(0); i < value.Units.Count; i++ {
					p := (*UnitStateRow)(cursor.Next())
					if p == nil {
						return false
					}
					{
						mark := payload8.Ids.Count
						n := UnitStateMeasureBody(&(*p), payload8.Ids)
						if n < 0 {
							return false
						}
						if !payload8.putLebPair(uint64(n)) {
							payload8.putLebWide(uint64(n))
						}
						if payload8.Measuring {
							payload8.Advance(n)
						} else {
							payload8.Ids.Truncate(mark)
							if !UnitStateSaveBody(&payload8, &(*p)) {
								return false
							}
						}
					}
				}
				if payload8.Overflow {
					return false
				}
				n := int64(1) + tableLebBytes(uint64(value.Units.Count)) + payload8.Offset
				if !w.putLebPair(uint64(n)) {
					w.putLebWide(uint64(n))
				}
				if w.Measuring {
					w.Advance(n)
				} else {
					w.Ids.Truncate(mark)
					w.Put8(13)
					if !w.putLebPair(uint64(value.Units.Count)) {
						w.putLebWide(uint64(value.Units.Count))
					}
					cursor := tableContainerCursorBegin((*tableContainer)(unsafe.Pointer(&value.Units)), int64(unsafe.Sizeof(*new(UnitStateRow))), w.Ids.Numbering.arena)
					for i := int32(0); i < value.Units.Count; i++ {
						p := (*UnitStateRow)(cursor.Next())
						if p == nil {
							return false
						}
						{
							mark := w.Ids.Count
							n := UnitStateMeasureBody(&(*p), w.Ids)
							if n < 0 {
								return false
							}
							if !w.putLebPair(uint64(n)) {
								w.putLebWide(uint64(n))
							}
							if w.Measuring {
								w.Advance(n)
							} else {
								w.Ids.Truncate(mark)
								if !UnitStateSaveBody(w, &(*p)) {
									return false
								}
							}
						}
					}
				}
			}
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func UnitsCheckLoadBody(r *TableReader, value *UnitsCheck) bool {
	UnitsCheckReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0xcaa83e18f46e5f54: // dir
			if kind != 17 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				index, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				r.Nodes.Resolve(&value.Dir, index, 0x704be0d8faaffc58, r.Report)
			}
		case 0x08b05d07b5566bef: // ok
			if kind != 1 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(1) {
				r.Report.Malformed = true
				return false
			}
			value.Ok = r.Get8() != 0
		case 0x4b78454e9ad2913c: // units
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
					break
				}
				if elemKind != 13 {
					if !tableKindWidens(elemKind, 13) {
						r.Report.KindMismatch++
						break
					}
					r.Report.Widened++
				}
				slot := (*tableContainer)(unsafe.Pointer(&value.Units))
				if !tableContainerFill(&sub.Nodes.Carve, slot, count, int64(unsafe.Sizeof(*new(UnitStateRow))), 8) {
					if sub.Nodes.Carve.Refused {
						r.Take(sub)
						return false
					}
					r.Report.Malformed = true
					break
				}
				slot.Count = 0
				for i := uint64(0); i < count; i++ {
					p := (*UnitStateRow)(tableContainerFillAt(&sub.Nodes.Carve, slot, int32(i), int64(unsafe.Sizeof(*new(UnitStateRow)))))
					if p == nil {
						r.Report.Malformed = true
						break
					}
					landed := false
					for once := true; once; once = false {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						UnitStateLoadBody(&elem, p)
						sub.Take(elem)
						if sub.Nodes.Carve.Refused {
							r.Nodes.Carve = sub.Nodes.Carve
							return false
						}
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							UnitStateReset(p)
						}
						landed = true
					}
					if !landed {
						if sub.Nodes.Carve.Worker != nil {
							tableContainerErase(sub.Nodes.Carve.Worker.Arena, slot, unsafe.Pointer(p), int64(unsafe.Sizeof(*p)))
						}
						break
					}
					if sub.Nodes.Carve.Worker == nil {
						slot.Count++
					}
				}
				r.Take(sub)
				if r.Nodes.Carve.Refused {
					return false
				}
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

