// SyncReportReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func SyncReportReadStrict(wire []byte) (*SyncReport, error) {
	var b SyncReportBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := SyncReportLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type SyncReportBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *SyncReportBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(SyncReport{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	SyncReportReset((*SyncReport)(p))
	return true
}
func (b *SyncReportBuilder) GetRoot() *SyncReport {
	if b.Arena.Locked {
		return nil
	}
	return (*SyncReport)(b.Arena.At(b.root))
}
func (b *SyncReportBuilder) AsConst() *SyncReport {
	if len(b.region) == 0 {
		return nil
	}
	return (*SyncReport)(unsafe.Pointer(&b.region[0]))
}
