// ShadowOutReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func ShadowOutReadStrict(wire []byte) (*ShadowOut, error) {
	var b ShadowOutBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := ShadowOutLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type ShadowOutBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ShadowOutBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ShadowOut{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ShadowOutReset((*ShadowOut)(p))
	return true
}
func (b *ShadowOutBuilder) GetRoot() *ShadowOut {
	if b.Arena.Locked {
		return nil
	}
	return (*ShadowOut)(b.Arena.At(b.root))
}
func (b *ShadowOutBuilder) AsConst() *ShadowOut {
	if len(b.region) == 0 {
		return nil
	}
	return (*ShadowOut)(unsafe.Pointer(&b.region[0]))
}
func (b *ShadowOutBuilder) Region() []byte { return b.region }
func (b *ShadowOutBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ShadowOutTableType(), &b.Arena)
}
func (b *ShadowOutBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ShadowOutTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ShadowOutBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ShadowOutTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ShadowOutBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// ShadowRecordReset restores ShadowRecord's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func ShadowRecordReset(value *ShadowRecord) {
	value.Binary = 0
	clear(value.At[:])
	value.AtLength = 0
	value.WallNs = 0
	ShadowPlanReset(&value.Plan)
}

