			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.At[:])
				value.AtLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 40 {
				keep = tableUtf8Clamp(sub.Buffer, 40)
				r.Report.Clamped++
			}
			clear(value.At[:])
			copy(value.At[:keep], sub.Buffer)
			value.AtLength = int32(keep)
