func ShadowRecordLoadMeasure(wire []byte) int64 {
	n, _, _ := tableRegionMeasure(wire, ShadowRecordTableType(), ShadowRecordTableType().NodeType, 2)
	return n
}
func ShadowRecordLoadMeasureReason(wire []byte) (int64, error) {
	size, _, _, reason := tableRegionMeasureReason(wire, ShadowRecordTableType(), ShadowRecordTableType().NodeType, 2)
	return size, tableRefuseError(reason)
}
func ShadowRecordLoad(region, wire []byte, report *TableReport) *ShadowRecord {
	return (*ShadowRecord)(tableRegionLoad(region, wire, ShadowRecordTableType(), ShadowRecordTableType().NodeType, 2, report))
}
func ShadowRecordMeasure(value *ShadowRecord, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), ShadowRecordTableType(), nil, true, arena, allocator)
}
func ShadowRecordMeasureReason(value *ShadowRecord, context ...TableWriteContext) (int64, error) {
	arena, allocator := tableWriteOptions(context)
	size, reason := tableRegionSaveReason(unsafe.Pointer(value), ShadowRecordTableType(), nil, true, arena, allocator)
	return size, tableRefuseError(reason)
}
func ShadowRecordSave(value *ShadowRecord, buffer []byte, context ...TableWriteContext) int64 {
	arena, allocator := tableWriteOptions(context)
	return tableRegionSave(unsafe.Pointer(value), ShadowRecordTableType(), buffer, false, arena, allocator)
}
func ShadowRecordLoadBuilder(b *ShadowRecordBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, ShadowRecordTableType(), ShadowRecordTableType().NodeType, 2, report)
}

// ShadowRecordReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func ShadowRecordReadStrict(wire []byte) (*ShadowRecord, error) {
	var b ShadowRecordBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := ShadowRecordLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type ShadowRecordBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ShadowRecordBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ShadowRecord{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ShadowRecordReset((*ShadowRecord)(p))
	return true
}
func (b *ShadowRecordBuilder) GetRoot() *ShadowRecord {
	if b.Arena.Locked {
		return nil
	}
	return (*ShadowRecord)(b.Arena.At(b.root))
}
func (b *ShadowRecordBuilder) AsConst() *ShadowRecord {
	if len(b.region) == 0 {
		return nil
	}
	return (*ShadowRecord)(unsafe.Pointer(&b.region[0]))
}
func (b *ShadowRecordBuilder) Region() []byte { return b.region }
func (b *ShadowRecordBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ShadowRecordTableType(), &b.Arena)
}
func (b *ShadowRecordBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ShadowRecordTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ShadowRecordBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ShadowRecordTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ShadowRecordBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

