const PartResultLoadRetainBuilder = "PartResult: retention requires a region round trip through the VARIABLE form"
const PartResultSaveRetainMessages = "PartResult: retention requires a region round trip through the VARIABLE form"

func PartResultLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *PartResult {
	return (*PartResult)(tableRegionLoadRetain(region, wire, PartResultTableType(), PartResultTableType().NodeType, 2, report, retain))
}
func PartResultMeasureRetain(value *PartResult, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), PartResultTableType(), nil, true, retain, nil, allocator...)
}
func PartResultSaveRetain(value *PartResult, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), PartResultTableType(), buffer, false, retain, report, allocator...)
}
func PartResultMeasureBodyRetain(value *PartResult, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !PartResultSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func PartResultSaveBodyRetain(w *TableRetainWriter, value *PartResult) bool {
	if !PartResultSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
