const PartTimeSaveRetainMessages = "PartTime: retention requires a region round trip through the VARIABLE form"

func PartTimeLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *PartTime {
	return (*PartTime)(tableRegionLoadRetain(region, wire, PartTimeTableType(), PartTimeTableType().NodeType, 0, report, retain))
}
func PartTimeMeasureRetain(value *PartTime, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), PartTimeTableType(), nil, true, retain, nil, allocator...)
}
func PartTimeSaveRetain(value *PartTime, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), PartTimeTableType(), buffer, false, retain, report, allocator...)
}
func PartTimeMeasureBodyRetain(value *PartTime, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !PartTimeSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func PartTimeSaveBodyRetain(w *TableRetainWriter, value *PartTime) bool {
	if !PartTimeSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
