func TickResultEmplace(worker *TableWorker, slot *TableRef) *TickResult {
	p, ref := worker.Alloc(int64(unsafe.Sizeof(TickResult{})))
	*slot = ref
	if p == nil {
		return nil
	}
	value := (*TickResult)(p)
	TickResultReset(value)
	return value
}
