func StagesLoadBuilder(b *StagesBuilder, wire []byte, report *TableReport) bool {
	return tableBuilderLoad(unsafe.Pointer(b.GetRoot()), b.root, &b.Main, wire, StagesTableType(), StagesTableType().NodeType, 0, report)
}

// StagesReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func StagesReadStrict(wire []byte) (*Stages, error) {
	var b StagesBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := StagesLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type StagesBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *StagesBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(Stages{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	StagesReset((*Stages)(p))
	return true
}
func (b *StagesBuilder) GetRoot() *Stages {
	if b.Arena.Locked {
		return nil
	}
	return (*Stages)(b.Arena.At(b.root))
}
func (b *StagesBuilder) AsConst() *Stages {
	if len(b.region) == 0 {
		return nil
	}
	return (*Stages)(unsafe.Pointer(&b.region[0]))
}
func (b *StagesBuilder) Region() []byte { return b.region }
func (b *StagesBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), StagesTableType(), &b.Arena)
}
func (b *StagesBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), StagesTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *StagesBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), StagesTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *StagesBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// MemberStatReset restores MemberStat's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MemberStatReset(value *MemberStat) {
	clear(value.Member[:])
	value.MemberLength = 0
	value.Cards = 0
	value.Failed = 0
	MeasureReset(&value.TakeWait)
	MeasureReset(&value.RunWall)
	MeasureReset(&value.ReportLag)
}

