// ReaderStatReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, its own builder, one typed reason.
func ReaderStatReadStrict(wire []byte) (*ReaderStat, error) {
	var b ReaderStatBuilder
	if !b.Init() {
		return nil, TableRefuseAllocationFailed
	}
	var report TableReport
	ok := ReaderStatLoadBuilder(&b, wire, &report)
	if err := report.Err(); err != nil || !ok {
		b.Shutdown()
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	if !b.Lock() {
		b.Shutdown()
		return nil, TableRefuseAllocationFailed
	}
	return b.AsConst(), nil
}

type ReaderStatBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ReaderStatBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ReaderStat{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ReaderStatReset((*ReaderStat)(p))
	return true
}
func (b *ReaderStatBuilder) GetRoot() *ReaderStat {
	if b.Arena.Locked {
		return nil
	}
	return (*ReaderStat)(b.Arena.At(b.root))
}
func (b *ReaderStatBuilder) AsConst() *ReaderStat {
	if len(b.region) == 0 {
		return nil
	}
	return (*ReaderStat)(unsafe.Pointer(&b.region[0]))
}
func (b *ReaderStatBuilder) Region() []byte { return b.region }
func (b *ReaderStatBuilder) PackMeasure() int64 {
	if b.Arena.Locked {
		return int64(len(b.region))
	}
	return tableRegionPackMeasure(unsafe.Pointer(b.GetRoot()), ReaderStatTableType(), &b.Arena)
}
func (b *ReaderStatBuilder) PackMeasureReason() (int64, error) {
	if b.Arena.Locked {
		return int64(len(b.region)), nil
	}
	size, reason := tableRegionPackMeasureReason(unsafe.Pointer(b.GetRoot()), ReaderStatTableType(), &b.Arena)
	return size, tableRefuseError(reason)
}
func (b *ReaderStatBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), ReaderStatTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *ReaderStatBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

